import { withEve } from "eve/vercel";

/**
 * Service graph for one Vercel project:
 *
 * - `web`: Next.js, serves every public path except `/eve/v1/*`.
 * - `eve`: the agent in `agent/`, generated by `withEve` and mounted at `/eve/v1/*`.
 * - `api`: FastAPI in `apps/api`. No route points at it, so it is private. `web` and `eve`
 *   reach it through a service binding that injects its URL as `BACKEND_URL`.
 */
const backendBinding = [
  { type: "service", service: "api", format: "url", env: "BACKEND_URL" },
] as const;

const config = await withEve({
  services: {
    web: {
      framework: "nextjs",
      root: "apps/web",
      bindings: backendBinding,
    },
    api: {
      root: "apps/api",
      entrypoint: "main:app",
      functions: { "**/*.py": { maxDuration: 60 } },
    },
  },
  routes: [{ src: "^(.*)$", destination: { type: "service", service: "web" } }],
});

// withEve owns the generated `eve` service, so attach the binding to whatever it generated.
// Never author an `eve` key here: Vercel's import flow can read this config without
// running withEve, and a partial `eve` service fails validation there.
export default {
  ...config,
  services: Object.fromEntries(
    Object.entries(config.services).map(([name, service]) => [
      name,
      service.framework === "eve" ? { ...service, bindings: backendBinding } : service,
    ]),
  ),
};
